#!/usr/bin/env python3
"""Verify the self-signed development TLS certificate in /app/ssl."""

import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path

CERT_PATH = Path("/app/ssl/server.crt")
KEY_PATH = Path("/app/ssl/server.key")
PEM_PATH = Path("/app/ssl/server.pem")


def openssl(*args: str) -> str:
    """Run an OpenSSL command and return its stdout."""
    result = subprocess.run(
        ["openssl", *args],
        capture_output=True,
        text=True,
        check=True,
    )
    return result.stdout.strip()


def fail(message: str) -> None:
    print(f"Certificate verification failed: {message}", file=sys.stderr)
    sys.exit(1)


def main() -> None:
    # 1. The certificate must exist and be loadable.
    if not CERT_PATH.is_file():
        fail(f"{CERT_PATH} does not exist")

    try:
        cert_text = openssl("x509", "-in", str(CERT_PATH), "-noout", "-text")
    except (subprocess.CalledProcessError, OSError) as exc:
        fail(f"unable to load certificate: {exc}")

    if "BEGIN CERTIFICATE" not in CERT_PATH.read_text():
        fail("certificate file is not in PEM format")

    # 2. Extract the Common Name.
    try:
        subject = openssl(
            "x509", "-in", str(CERT_PATH), "-noout", "-subject", "-nameopt", "RFC2253"
        )
    except subprocess.CalledProcessError as exc:
        fail(f"unable to read subject: {exc}")

    common_name = None
    for part in subject.replace("subject=", "").split(","):
        if part.startswith("CN="):
            common_name = part[3:]
            break
    if not common_name:
        fail("certificate has no Common Name")

    # 3. Extract and validate the expiration date.
    try:
        not_after_raw = openssl("x509", "-in", str(CERT_PATH), "-noout", "-enddate")
    except subprocess.CalledProcessError as exc:
        fail(f"unable to read expiration date: {exc}")

    expires_at = datetime.strptime(
        not_after_raw.replace("notAfter=", "").strip(), "%b %d %H:%M:%S %Y %Z"
    ).replace(tzinfo=timezone.utc)
    expiration_date = expires_at.strftime("%Y-%m-%d")

    if expires_at <= datetime.now(timezone.utc):
        fail(f"certificate expired on {expiration_date}")

    # 4. Sanity checks on the key pairing and combined PEM file.
    if not KEY_PATH.is_file():
        fail(f"{KEY_PATH} does not exist")

    cert_pubkey = openssl("x509", "-in", str(CERT_PATH), "-noout", "-pubkey")
    key_pubkey = openssl("rsa", "-in", str(KEY_PATH), "-pubout")
    if cert_pubkey != key_pubkey:
        fail("private key does not match the certificate")

    if not PEM_PATH.is_file():
        fail(f"{PEM_PATH} does not exist")
    pem_text = PEM_PATH.read_text()
    if "BEGIN PRIVATE KEY" not in pem_text and "BEGIN RSA PRIVATE KEY" not in pem_text:
        fail("combined PEM file is missing the private key")
    if "BEGIN CERTIFICATE" not in pem_text:
        fail("combined PEM file is missing the certificate")

    # 5. Report details.
    print(f"Certificate file: {CERT_PATH}")
    print(f"Common Name (CN): {common_name}")
    print(f"Expiration date: {expiration_date}")
    print("Certificate verification successful")


if __name__ == "__main__":
    main()
PYEOF
